// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.valueoverlay;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Locale;
import java.util.Random;
import java.util.concurrent.atomic.AtomicReference;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.EnumSource;

class ValueOverlayPageAccessTest {

	@ParameterizedTest
	@EnumSource(PageCodec.Mode.class)
	void readsEveryModeAtNonzeroSlabOffsets(PageCodec.Mode mode) {
		PhysicalRecord[] records = records(mode);
		byte[] page = page(mode, records);
		try (NativeSlabAllocator allocator = new NativeSlabAllocator(1 << 20)) {
			allocator.copy(new byte[97]);
			long handle = allocator.copy(page);
			assertTrue(NativeSlabAllocator.offset(handle) > 0);
			// Adjacent bytes must never become visible as part of a record or malformed command.
			allocator.copy(new byte[4096]);
			for (int slot = 0; slot < records.length; slot++) {
				byte[] expected = records[slot].bytes();
				assertArrayEquals(expected, PageCodec.read(allocator, handle, slot).bytes());
				RecordByteAccess source = PageCodec.openRecord(allocator, handle, slot);
				assertEquals(expected.length, source.length());
				for (int i = 0; i < expected.length; i++) {
					assertEquals(expected[i] & 255, source.byteAt(i));
				}
				Random random = new Random(77104 + slot);
				for (int i = 0; i < 30; i++) {
					int from = random.nextInt(expected.length + 1);
					int length = random.nextInt(expected.length - from + 1);
					byte[] target = new byte[length + 8];
					Arrays.fill(target, (byte) 73);
					source.copy(from, target, 4, length);
					assertArrayEquals(Arrays.copyOfRange(expected, from, from + length),
							Arrays.copyOfRange(target, 4, 4 + length));
					assertEquals(73, target[3]);
					assertEquals(73, target[4 + length]);
				}
				assertThrows(IndexOutOfBoundsException.class, () -> source.byteAt(-1));
				assertThrows(IndexOutOfBoundsException.class, () -> source.byteAt(expected.length));
				assertThrows(IndexOutOfBoundsException.class, () -> source.copy(expected.length, new byte[1], 0, 1));
				assertThrows(IndexOutOfBoundsException.class, () -> source.copy(0, new byte[1], 1, 1));
				source.copy(expected.length, new byte[0], 0, 0);
				AtomicReference<ValueStoreRecordVisitor.Record> escaped = new AtomicReference<>();
				assertTrue(ValueStoreRecordVisitor.visit(source, record -> {
					escaped.set(record);
					byte[] lexical = Arrays.copyOfRange(expected, 3, expected.length);
					assertTrue(record.lexicalEquals(lexical));
					assertEquals(5, record.datatypeId());
				}));
				assertThrows(IllegalStateException.class, () -> escaped.get().kind());
			}
		}
	}

	@Test
	void nestedVisitsDoNotInvalidateOrOverwriteOuterRecord() {
		PhysicalRecord[] records = records(PageCodec.Mode.TOKEN);
		try (NativeSlabAllocator allocator = new NativeSlabAllocator(1 << 20)) {
			long handle = allocator.copy(page(PageCodec.Mode.TOKEN, records));
			AtomicReference<ValueStoreRecordVisitor.Record> inner = new AtomicReference<>();
			assertTrue(ValueStoreRecordVisitor.visit(PageCodec.openRecord(allocator, handle, 0), outer -> {
				byte[] expected = Arrays.copyOfRange(records[0].bytes(), 3, records[0].bytes().length);
				assertTrue(outer.lexicalEquals(expected));
				assertTrue(ValueStoreRecordVisitor.visit(PageCodec.openRecord(allocator, handle, 1), inner::set));
				assertThrows(IllegalStateException.class, () -> inner.get().kind());
				assertTrue(outer.lexicalEquals(expected));
			}));
		}
	}

	@ParameterizedTest
	@EnumSource(PageCodec.Mode.class)
	void rejectsTruncatedPageDespiteLargerBackingSlab(PageCodec.Mode mode) {
		byte[] page = page(mode, records(mode));
		ByteBuffer header = ByteBuffer.wrap(page).order(ByteOrder.LITTLE_ENDIAN);
		// The slab still contains all original bytes. The declared page boundary excludes the payload.
		header.putInt(mode == PageCodec.Mode.VECTOR ? 16 : 28, 32);
		assertCorrupt(page, false);
	}

	@ParameterizedTest
	@EnumSource(value = PageCodec.Mode.class, names = "VECTOR", mode = EnumSource.Mode.EXCLUDE)
	void rejectsRecordOutsideDeclaredPayload(PageCodec.Mode mode) {
		byte[] page = page(mode, records(mode));
		ByteBuffer header = ByteBuffer.wrap(page).order(ByteOrder.LITTLE_ENDIAN);
		// The header is valid, but the first checkpoint puts a nonempty record beyond its payload.
		header.putInt(32, header.getInt(24));
		assertCorrupt(page, false);
	}

	@Test
	void rejectsVectorFieldOutsideDeclaredPage() {
		byte[] page = page(PageCodec.Mode.VECTOR, records(PageCodec.Mode.VECTOR));
		ByteBuffer header = ByteBuffer.wrap(page).order(ByteOrder.LITTLE_ENDIAN);
		assertTrue(header.getInt(12) > 0);
		int firstField = 20 + header.getInt(8);
		// The field exists, but its packed values cross the page boundary into adjacent slab storage.
		header.putInt(firstField + 16, page.length - 1);
		assertCorrupt(page, false);
	}

	@Test
	void rejectsTokenDictionaryAndLiteralRunsOutsideTheirRanges() {
		byte[] page = page(PageCodec.Mode.TOKEN, records(PageCodec.Mode.TOKEN));
		ByteBuffer header = ByteBuffer.wrap(page).order(ByteOrder.LITTLE_ENDIAN);
		int dictionary = 32 + 4 * header.getInt(12);
		int payload = header.getInt(20);
		byte[] badDictionary = page.clone();
		// Token zero must be bounded by the dictionary, not by the enclosing page/slab.
		badDictionary[payload] = 0;
		ByteBuffer.wrap(badDictionary).order(ByteOrder.LITTLE_ENDIAN).putShort(dictionary + 3, (short) 65535);
		assertCorrupt(badDictionary, true);
		byte[] badCommand = page.clone();
		badCommand[payload] = (byte) 255;
		assertCorrupt(badCommand, true);
		// One-record TOKEN page whose sole encoded byte claims a 128-byte literal run.
		byte[] truncatedRun = new byte[65];
		ByteBuffer h = ByteBuffer.wrap(truncatedRun).order(ByteOrder.LITTLE_ENDIAN);
		h.putInt(0, PageCodec.MAGIC).putShort(4, (short) 1).put(6, (byte) 1).put(7, (byte) 2);
		h.putShort(10, (short) 5).putInt(12, 1).putInt(16, 48).putInt(20, 64).putInt(24, 1).putInt(28, 65);
		h.put(36, (byte) 1).put(48, (byte) 1).put(64, (byte) 191);
		assertCorrupt(truncatedRun, true);
	}

	@Test
	void rawLargeRecordPreservesCopyBounds() {
		byte[] bytes = literal("large record header and bytes");
		PhysicalRecord[] records = { new PhysicalRecord(bytes, true, bytes.length) };
		byte[] page = PageCodec.seal(records, 1, 16, Integer.MAX_VALUE, false, 0, 0, false).pageBytes();
		try (NativeSlabAllocator allocator = new NativeSlabAllocator(1 << 20)) {
			allocator.copy(new byte[97]);
			RecordByteAccess source = PageCodec.openRecord(allocator, allocator.copy(page), 0);
			byte[] actual = new byte[source.length()];
			source.copy(0, actual, 0, actual.length);
			assertArrayEquals(bytes, actual);
			assertThrows(IndexOutOfBoundsException.class, () -> source.byteAt(actual.length));
		}
	}

	private static void assertCorrupt(byte[] page, boolean readLength) {
		try (NativeSlabAllocator allocator = new NativeSlabAllocator(1 << 20)) {
			allocator.copy(new byte[97]);
			long handle = allocator.copy(page);
			allocator.copy(new byte[4096]);
			assertThrows(IllegalStateException.class, () -> {
				RecordByteAccess source = PageCodec.openRecord(allocator, handle, 0);
				if (readLength) {
					source.length();
				}
			});
		}
	}

	private static PhysicalRecord[] records(PageCodec.Mode mode) {
		PhysicalRecord[] records = new PhysicalRecord[64];
		for (int i = 0; i < records.length; i++) {
			String label = switch (mode) {
			case RAW -> "hé/e\u0301/漢字/😀/" + i;
			case FRONT, PREFIX -> "long/common/path/".repeat(20) + i;
			case TOKEN -> i + "/" + "common segment in the middle of the value; ".repeat(10) + i;
			case VECTOR -> String.format(Locale.ROOT, "-00%08d.000e+03/Ab%04x/2026-09-%02d", i, i, i % 27 + 1);
			};
			byte[] bytes = literal(label);
			records[i] = new PhysicalRecord(bytes, false, bytes.length);
		}
		return records;
	}

	private static byte[] page(PageCodec.Mode mode, PhysicalRecord[] records) {
		if (mode == PageCodec.Mode.VECTOR) {
			byte[] page = VectorPageCodec.encode(records, records.length, true);
			assertNotNull(page);
			return page;
		}
		PageCodec.SealedPage page = PageCodec.seal(records, records.length,
				mode == PageCodec.Mode.FRONT ? 16 : 1, mode == PageCodec.Mode.RAW ? Integer.MAX_VALUE : 16,
				mode == PageCodec.Mode.TOKEN, 1024, 48, false, true, mode == PageCodec.Mode.PREFIX);
		assertEquals(mode, page.mode());
		return page.pageBytes();
	}

	private static byte[] literal(String label) {
		byte[] lexical = label.getBytes(StandardCharsets.UTF_8);
		byte[] bytes = new byte[lexical.length + 3];
		bytes[0] = 1;
		bytes[1] = 5;
		System.arraycopy(lexical, 0, bytes, 3, lexical.length);
		return bytes;
	}
}
